  "content": "import json, os, sys
import numpy as np
import soundfile as sf

ROOT = r"<run>"


def pulses_of(path, thr=0.22, min_gap=0.06, min_dur=0.05):
    data, sr = sf.read(path)
    data = np.asarray(data, dtype=np.float64)
    if data.ndim > 1:
        data = data.mean(axis=1)
    hop, win = 128, 512
    n = (len(data) - win) // hop
    if n <= 0:
        return []
    env = np.array([np.sqrt(np.mean(data[i*hop:i*hop+win]**2)) for i in range(n)])
    e = env / (env.max() + 1e-12)
    t = np.arange(n) * hop / sr
    # smooth
    k = 5
    e = np.convolve(e, np.ones(k)/k, mode="same")
    on = e > thr
    segs = []
    i = 0
    while i < n:
        if on[i]:
            j = i
            while j < n and on[j]:
                j += 1
            if t[j-1] - t[i] >= min_dur:
                segs.append([round(float(t[i]), 3), round(float(t[j-1]), 3)])
            i = j
        else:
            i += 1
    # merge close segments
    merged = []
    for a, b in segs:
        if merged and a - merged[-1][1] < min_gap:
            merged[-1][1] = b
        else:
            merged.append([a, b])
    return merged


if __name__ == "__main__":
    d = sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, "work", "grp40")
    files = sorted(f for f in os.listdir(d) if f.endswith(".wav"))
    for f in files:
        p = pulses_of(os.path.join(d, f))
        print(f"{f:20s} n={len(p):2d}  {p}")
