import re
import sys

ROOT = r"<run>"
src_segs = json.load(open(ROOT + r"\input\segments.json", encoding="utf-8"))["segments"]
out_segs = json.load(open(ROOT + r"\output\segments.json", encoding="utf-8"))["segments"]
srt = open(ROOT + r"\output\zh-CN.srt", encoding="utf-8-sig").read()

problems = []

# --- parse SRT ---
blocks = re.split(r"\n\s*\n", srt.replace("\r\n", "\n").strip())
cues = []
for blk in blocks:
    lines = blk.split("\n")
    if len(lines) < 3:
        problems.append(f"block with <3 lines: {blk!r}")
        continue
    idx = int(lines[0])
    m = re.match(r"^(\d{2}):(\d{2}):(\d{2}),(\d{3}) --> (\d{2}):(\d{2}):(\d{2}),(\d{3})$", lines[1])
    if not m:
        problems.append(f"cue {idx}: bad timestamp {lines[1]!r}")
        continue
    g = [int(x) for x in m.groups()]
    st = g[0]*3600 + g[1]*60 + g[2] + g[3]/1000
    en = g[4]*3600 + g[5]*60 + g[6] + g[7]/1000
    text = "\n".join(lines[2:])
    cues.append((idx, st, en, text))

print("parsed cues:", len(cues))

# numbering 1..N
if [c[0] for c in cues] != list(range(1, len(cues) + 1)):
    problems.append("cue numbering not 1..N increasing")

# valid, non-overlapping, monotonic
prev_en = -1
for idx, st, en, tx in cues:
    if en <= st:
        problems.append(f"cue {idx}: end<=start")
    if st < prev_en - 1e-9:
        problems.append(f"cue {idx}: overlaps previous (start {st} < prev end {prev_en})")
    prev_en = en

# line / char / speed limits
def nb(s):
    return len(re.sub(r"\s", "", s))

for idx, st, en, tx in cues:
    lines = tx.split("\n")
    if len(lines) > 2:
        problems.append(f"cue {idx}: {len(lines)} lines")
    for ln in lines:
        if nb(ln) > 22:
            problems.append(f"cue {idx}: line {nb(ln)} chars > 22 :: {ln}")
    dur = en - st
    cps = nb(tx) / dur
    if cps > 9:
        problems.append(f"cue {idx}: {cps:.2f} chars/s > 9")

# --- segment containment + mapping ---
seg_bounds = {s["segment_id"]: (float(s["start"]), float(s["end"])) for s in src_segs}
cue_ids_all = []
covered = set()
for s in out_segs:
    sid = s["segment_id"]
    if sid not in seg_bounds:
        problems.append(f"unknown segment in output: {sid}")
        continue
    a, b = seg_bounds[sid]
    for cid in s["cue_ids"]:
        cue_ids_all.append(cid)
        covered.add(sid)

if len(cue_ids_all) != len(set(cue_ids_all)):
    problems.append("some cue mapped to more than one segment")
if sorted(set(cue_ids_all)) != list(range(1, len(cues) + 1)):
    missing = set(range(1, len(cues) + 1)) - set(cue_ids_all)
    extra = set(cue_ids_all) - set(range(1, len(cues) + 1))
    problems.append(f"cue_ids coverage mismatch missing={sorted(missing)} extra={sorted(extra)}")

if [s["segment_id"] for s in out_segs] != [s["segment_id"] for s in src_segs]:
    problems.append("output segments list does not match manifest order/ids")

# each cue lies inside its declared segment
cid2seg = {}
for s in out_segs:
    for cid in s["cue_ids"]:
        cid2seg[cid] = s["segment_id"]
for idx, st, en, tx in cues:
    sid = cid2seg.get(idx)
    if sid is None:
        problems.append(f"cue {idx} not mapped to any segment")
        continue
    a, b = seg_bounds[sid]
    if not (a <= st < en <= b + 1e-9):
        problems.append(f"cue {idx} {st:.3f}-{en:.3f} outside {sid} [{a},{b}]")

# uncertainty note present for every segment
for s in out_segs:
    if "uncertainty" not in s:
        problems.append(f"{s['segment_id']}: missing uncertainty key")

print("segments:", len(out_segs), "| cues mapped:", len(cue_ids_all))
print("segments with cues:", len(covered), "| without:", [s['segment_id'] for s in out_segs if not s['cue_ids']])

if problems:
    print("\nPROBLEMS:")
    for p in problems:
        print("  -", p)
    sys.exit(1)
print("\nALL CHECKS PASSED")
",
